<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute } from 'vue-router';
import axios from 'axios';
import AppIcon from '../components/base/AppIcon.vue';
import GameKitExpiredState from '../components/gamekit/GameKitExpiredState.vue';

const route = useRoute();
const loading = ref(true), error = ref(''), session = ref(null), cards = ref([]);
const openCards = ref([]), matchedPairIds = ref(new Set()), attempts = ref(0), feedback = ref('');
const completed = ref(false), resultSent = ref(false), sendingResult = ref(false), startedAt = ref(Date.now());
let mismatchTimer;
let finishTimer;
const pairCount = computed(() => session.value?.pairs?.length ?? 0);
const matchedCount = computed(() => matchedPairIds.value.size);
const isOpen = (card) => openCards.value.some(item => item.key === card.key);
const isMatched = (card) => matchedPairIds.value.has(card.pairId);
const accentClass = (accent) => ({ sky: 'bg-sky-50 text-sky-700', lavender: 'bg-violet-50 text-violet-700', clay: 'bg-orange-50 text-orange-700', sun: 'bg-yellow-50 text-yellow-700', rose: 'bg-rose-50 text-rose-700', sage: 'bg-emerald-50 text-emerald-700', amber: 'bg-amber-50 text-amber-700', blue: 'bg-blue-50 text-blue-700', moss: 'bg-lime-50 text-lime-700', violet: 'bg-purple-50 text-purple-700', teal: 'bg-teal-50 text-teal-700', gold: 'bg-yellow-50 text-yellow-700' }[accent] ?? 'bg-[var(--spa-accent-soft)] text-[var(--spa-accent)]');
const shuffle = (items) => [...items].sort(() => Math.random() - 0.5);
const sendResult = async () => { sendingResult.value = true; try { await axios.post('/api/gamekit/memory/play/' + route.params.token + '/result', { attempts: attempts.value, matched_pairs: matchedCount.value, duration_seconds: Math.max(0, Math.round((Date.now() - startedAt.value) / 1000)), completed: completed.value }); resultSent.value = true; } catch (e) { error.value = e?.response?.data?.message ?? 'Resultado pronto. Tente enviar novamente.'; } finally { sendingResult.value = false; } };
const finishIfComplete = () => { if (matchedCount.value >= pairCount.value) { feedback.value = 'Você encontrou todos os pares. Que associação foi mais interessante para você?'; clearTimeout(finishTimer); finishTimer = setTimeout(() => { completed.value = true; sendResult(); }, 5200); } };
const chooseCard = (card) => { if (completed.value || isMatched(card) || isOpen(card) || openCards.value.length >= 2) return; feedback.value = ''; openCards.value = [...openCards.value, card]; if (openCards.value.length !== 2) return; attempts.value += 1; const [first, second] = openCards.value; if (first.pairId === second.pairId) { matchedPairIds.value = new Set([...matchedPairIds.value, first.pairId]); openCards.value = []; feedback.value = first.feedback; finishIfComplete(); } else { clearTimeout(mismatchTimer); mismatchTimer = setTimeout(() => { openCards.value = []; feedback.value = 'Essa combinação não formou um par. Observe com calma e tente outra associação.'; }, 850); } };
onMounted(async () => { try { const { data } = await axios.get('/api/gamekit/memory/play/' + route.params.token); session.value = data.session; cards.value = shuffle(session.value.pairs.flatMap(pair => [{ key: pair.id + '-a', pairId: pair.id, label: pair.label_a, feedback: pair.feedback, icon: pair.icon, accent: pair.accent }, { key: pair.id + '-b', pairId: pair.id, label: pair.label_b, feedback: pair.feedback, icon: pair.icon, accent: pair.accent }])); startedAt.value = Date.now(); } catch (e) { error.value = e?.response?.data?.message ?? 'Esta atividade não está mais disponível.'; } finally { loading.value = false; } });
</script>

<template>
    <main class="min-h-screen bg-[#f4f6f3] px-4 py-6 sm:px-6 sm:py-10"><section class="mx-auto w-full max-w-5xl"><div v-if="loading" class="rounded-3xl bg-white p-12 text-center text-sm text-[var(--spa-ink-muted)] shadow-sm">Preparando o jogo...</div><GameKitExpiredState v-else-if="error && !session" :message="error" /><div v-else-if="session" class="space-y-5"><header class="rounded-3xl bg-white p-5 shadow-sm sm:p-7"><div class="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker">GameKit Psi · Jogo da memória</p><h1 class="mt-1 text-2xl font-semibold text-[var(--spa-ink)] sm:text-3xl">{{ session.name }}</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-[var(--spa-ink-muted)]">Encontre os pares, perceba as relações e siga no seu ritmo.</p></div><div class="flex gap-2 text-sm"><span class="rounded-full bg-[var(--spa-accent-soft)] px-3 py-2 font-semibold text-[var(--spa-accent)]">{{ matchedCount }}/{{ pairCount }} pares</span><span class="rounded-full bg-[var(--spa-surface-muted)] px-3 py-2 text-[var(--spa-ink-muted)]">{{ attempts }} tentativas</span></div></div><div class="mt-5 h-2 overflow-hidden rounded-full bg-[var(--spa-surface-muted)]"><div class="h-full rounded-full bg-[var(--spa-accent)] transition-all duration-500" :style="{ width: ((pairCount ? matchedCount / pairCount : 0) * 100) + '%' }"></div></div></header><section v-if="!completed" class="rounded-3xl bg-white p-4 shadow-sm sm:p-7"><div class="grid grid-cols-2 gap-3 sm:grid-cols-4 sm:gap-4"><button v-for="card in cards" :key="card.key" class="relative aspect-[1.2] overflow-hidden rounded-2xl border text-center transition duration-300 focus:outline-none focus:ring-2 focus:ring-[var(--spa-accent)] sm:aspect-[1.35]" :class="isOpen(card) || isMatched(card) ? (isMatched(card) ? 'border-2 border-[var(--spa-accent)] bg-[var(--spa-accent-soft)] shadow-[0_0_0_4px_rgba(65,95,118,.16)]' : 'border-[var(--spa-accent)] bg-white shadow-md') : 'border-[var(--spa-border)] bg-[var(--spa-accent)] hover:-translate-y-0.5 hover:shadow-md'" type="button" :aria-label="isOpen(card) || isMatched(card) ? card.label : 'Carta fechada'" @click="chooseCard(card)"><span v-if="isOpen(card) || isMatched(card)" class="flex h-full flex-col items-center justify-center gap-2 p-3"><span class="flex size-14 items-center justify-center rounded-2xl text-lg font-semibold shadow-sm" :class="accentClass(card.accent)"><AppIcon :name="card.icon || 'Sparkles'" class="size-8" /></span><span class="text-sm font-semibold text-[var(--spa-ink)] sm:text-base">{{ card.label }}</span><span v-if="isMatched(card)" class="rounded-full bg-white/80 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-[var(--spa-accent)]">Par encontrado</span></span><span v-else class="flex h-full items-center justify-center"><span class="flex size-11 items-center justify-center rounded-2xl border border-white/40 bg-white/15 text-xl text-white"><AppIcon name="Heart" class="size-5" /></span></span></button></div><p class="mt-5 text-center text-sm text-[var(--spa-ink-muted)]">Vire duas cartas por vez para encontrar uma associação.</p></section><section v-if="feedback" class="rounded-3xl border border-[#c9d8cd] bg-[#edf4ef] p-5 text-sm leading-6 text-[#365341]"><p class="font-semibold">{{ feedback }}</p></section><section v-if="completed" class="rounded-3xl bg-white p-7 text-center shadow-sm sm:p-10"><span class="mx-auto flex size-14 items-center justify-center rounded-2xl bg-[var(--spa-accent-soft)] text-[var(--spa-accent)]"><AppIcon name="Trophy" class="size-7" /></span><h2 class="mt-4 text-2xl font-semibold text-[var(--spa-ink)]">Atividade concluída</h2><p class="mx-auto mt-2 max-w-lg text-sm leading-6 text-[var(--spa-ink-muted)]">Você encontrou todos os pares em {{ attempts }} tentativas. Converse com seu psicólogo sobre as associações que chamaram sua atenção.</p><p v-if="resultSent" class="mt-4 text-sm font-semibold text-[#365341]">Resultado enviado com segurança.</p><button v-else class="btn-primary mt-5" type="button" :disabled="sendingResult" @click="sendResult">{{ sendingResult ? 'Enviando...' : 'Enviar resultado novamente' }}</button></section><p v-if="error && session" class="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{{ error }}</p></div></section></main>
</template>
